(function(root){
 const sizes={P:{parts:2,factor:.6},M:{parts:2,factor:.8},G:{parts:2,factor:1},GG:{parts:4,factor:1.3},'Meio metro':{parts:3,factor:1.5},Metro:{parts:6,factor:2.6}};
 const defaultPizzaPrices={P:3000,M:4000,G:6000,GG:7000,'Meio metro':9000,Metro:12000};
 const cents=n=>Math.round(Number(n)*100);
 function pizzaPrice(size,flavors,borders,extras,products,basePrices=defaultPizzaPrices){if(!sizes[size]||!flavors.length)throw Error('Escolha o tamanho e os sabores.');if(flavors.length!==sizes[size].parts)throw Error('Preencha todas as partes.');const byId=id=>products.find(p=>p.id===id);const selected=flavors.map(byId);if(selected.some(p=>!p||p.kind!=='pizza'||!p.available||!Number.isInteger(p.surcharge||0)||(p.surcharge||0)<0))throw Error('Sabor indisponível ou sem preço.');if(!Number.isInteger(basePrices[size])||basePrices[size]<0)throw Error('Preço padrão do tamanho inválido.');const base=basePrices[size]+Math.max(...selected.map(p=>p.surcharge||0));let border=0;if(borders.length){const ps=borders.map(byId);if(ps.some(p=>!p||!p.available||p.kind!=='borda'))throw Error('Borda indisponível.');border=Math.round(ps.reduce((s,p)=>s+p.prices[size],0)/ps.length);}if(extras.reduce((s,e)=>s+e.qty,0)>10)throw Error('Limite de 10 adicionais por pizza.');const extra=extras.reduce((s,e)=>{const p=byId(e.id);if(!p||p.kind!=='adicional'||!p.available||!Number.isInteger(e.qty)||e.qty<1)throw Error('Adicional inválido.');return s+p.prices[size]*e.qty;},0);return base+border+extra;}
 function split(total,people){if(!Number.isInteger(people)||people<1)throw Error('Informe pelo menos uma pessoa.');return Array.from({length:people},(_,i)=>Math.floor(total/people)+(i<total%people?1:0));}
 function subtotal(order){return order.items.filter(i=>!i.cancelled).reduce((s,i)=>s+i.price*i.qty,0);}
 function service(order){return order.type==='mesa'?Math.round(subtotal(order)*.1):0;}
 function total(order){return Math.max(0,subtotal(order)+service(order)+(order.type==='delivery'?(order.fee||0):0)-(order.discount||0));}
 function paid(order){return order.payments.reduce((s,p)=>s+p.amount,0);}
 function compose(flavors,products){const grouped={};flavors.forEach(id=>grouped[id]=(grouped[id]||0)+1);const gcd=(a,b)=>b?gcd(b,a%b):a;return Object.entries(grouped).map(([id,n])=>{const d=gcd(n,flavors.length),fraction=n===flavors.length?'Inteira':n*2===flavors.length?'Metade':(n/d)+'/'+(flavors.length/d);return `${fraction} ${(products.find(p=>p.id===id)||{}).name||id}`;}).join(' + ');}
 function validateStock(order,stock,products){for(const [id,qty]of Object.entries(order.items.filter(i=>!i.cancelled).reduce((s,i)=>{const p=products.find(p=>p.id===i.product);if(p&&p.kind==='bebida')s[i.product]=(s[i.product]||0)+i.qty;return s;},{}))){const p=products.find(p=>p.id===id);if(!p.negative&&(stock[id]||0)<qty)throw Error(`Estoque insuficiente: ${p.name}.`);}}
 const api={sizes,defaultPizzaPrices,cents,pizzaPrice,split,subtotal,service,total,paid,compose,validateStock};root.DomDomain=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
